package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.entity.chat.ChatAttachment; import EmployeeManagementSystem.repository.chat.ChatAttachmentRepository; import EmployeeManagementSystem.repository.ChatConversationRepository;
import jakarta.validation.constraints.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
import java.io.*; import java.net.*; import java.nio.file.*; import java.security.*; import java.util.*;
@RestController @RequestMapping("/api/chat") public class TeamChatAttachmentController {
 private final ChatConversationRepository conversations; private final ChatAttachmentRepository attachments; private final Path root; private final boolean scanRequired; private final String clamHost; private final int clamPort;
 public TeamChatAttachmentController(ChatConversationRepository c,ChatAttachmentRepository a,@Value("${chat.attachments.dir:uploads/chat}") String dir,@Value("${chat.antivirus.required:true}") boolean required,@Value("${chat.antivirus.host:127.0.0.1}") String host,@Value("${chat.antivirus.port:3310}") int port)throws IOException {conversations=c;attachments=a;root=Paths.get(dir).toAbsolutePath().normalize();Files.createDirectories(root);scanRequired=required;clamHost=host;clamPort=port;}
 public record AttachmentView(Long id,Long conversationId,String uploadedBy,String originalName,String contentType,long sizeBytes,String scanStatus,java.time.Instant createdAt){}
 @PostMapping(value="/conversations/{id}/attachments",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public ResponseEntity<?> upload(@PathVariable Long id,@RequestPart("file") MultipartFile file,Authentication auth)throws IOException {if(!isMember(id,auth))return ResponseEntity.status(403).body(Map.of("message","Not a conversation member"));if(file.isEmpty()||file.getSize()>10*1024*1024)return ResponseEntity.badRequest().body(Map.of("message","File must be between 1 byte and 10 MB"));String name=safeFilename(file.getOriginalFilename());if(name.length()>200)name=name.substring(name.length()-200);String ext=name.contains(".")?name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT):"";Map<String,String> allowed=Map.of("pdf","application/pdf","png","image/png","jpg","image/jpeg","jpeg","image/jpeg","txt","text/plain","csv","text/csv","docx","application/vnd.openxmlformats-officedocument.wordprocessingml.document","xlsx","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");if(!allowed.containsKey(ext))return ResponseEntity.badRequest().body(Map.of("message","File type is not allowed"));byte[] bytes=file.getBytes();if(!signatureMatches(ext,bytes))return ResponseEntity.badRequest().body(Map.of("message","File signature does not match its extension"));String sha=sha256(bytes);String status="UNSCANNED";try{String verdict=clamScan(bytes);if("OK".equals(verdict))status="CLEAN";else return ResponseEntity.status(422).body(Map.of("message","File was rejected by malware scanning"));}catch(Exception e){if(scanRequired)return ResponseEntity.status(503).body(Map.of("message","Malware scanner is unavailable; upload blocked for safety"));}String storage=UUID.randomUUID().toString();Path target=root.resolve(storage).normalize();if(!target.getParent().equals(root))return ResponseEntity.status(400).build();Files.write(target,bytes,StandardOpenOption.CREATE_NEW);try{ChatAttachment a=attachments.saveAndFlush(new ChatAttachment(id,auth.getName(),name,storage,allowed.get(ext),bytes.length,sha,status));return ResponseEntity.status(201).body(view(a));}catch(RuntimeException failure){Files.deleteIfExists(target);throw failure;}}
 @GetMapping("/conversations/{id}/attachments") public ResponseEntity<?> list(@PathVariable Long id,Authentication auth){if(!isMember(id,auth))return ResponseEntity.status(403).body(Map.of("message","Not a conversation member"));return ResponseEntity.ok(attachments.findByConversationIdOrderByCreatedAtDesc(id).stream().map(this::view).toList());}
 @GetMapping("/attachments/{id}/download") public ResponseEntity<?> download(@PathVariable Long id,Authentication auth)throws IOException {ChatAttachment a=attachments.findById(id).orElse(null);if(a==null)return ResponseEntity.notFound().build();if(!isMember(a.getConversationId(),auth))return ResponseEntity.status(403).build();if(!"CLEAN".equals(a.getScanStatus()))return ResponseEntity.status(423).body(Map.of("message","Attachment is not cleared for download"));Path f=root.resolve(a.getStorageName()).normalize();if(!f.getParent().equals(root)||!Files.isRegularFile(f,LinkOption.NOFOLLOW_LINKS))return ResponseEntity.notFound().build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(a.getContentType())).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(a.getOriginalName(),java.nio.charset.StandardCharsets.UTF_8).build().toString()).header("X-Content-Type-Options","nosniff").header("Cache-Control","private, no-store").body(new FileSystemResource(f));}
 static String safeFilename(String name){return EmployeeManagementSystem.service.AttachmentScanClient.safeFilename(name);}
 private boolean isMember(Long id,Authentication auth){return conversations.findById(id).map(c->auth!=null&&c.getMembers().contains(auth.getName())).orElse(false);}
 private AttachmentView view(ChatAttachment a){return new AttachmentView(a.getId(),a.getConversationId(),a.getUploadedBy(),a.getOriginalName(),a.getContentType(),a.getSizeBytes(),a.getScanStatus(),a.getCreatedAt());}
 String clamScan(byte[] bytes)throws IOException {return EmployeeManagementSystem.service.AttachmentScanClient.scan(bytes,clamHost,clamPort);}
 private boolean signatureMatches(String ext,byte[] bytes){return EmployeeManagementSystem.service.ChatFileRules.matches(ext,bytes);}
 private String sha256(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}
}
